from collections import Counter

def step(alive):
    """One generation. `alive` is a set of (x, y) cells on an unlimited grid."""
    counts = Counter((x + dx, y + dy)
                     for x, y in alive
                     for dx in (-1, 0, 1) for dy in (-1, 0, 1)
                     if (dx, dy) != (0, 0))
    return {cell for cell, n in counts.items()
            if n == 3 or (n == 2 and cell in alive)}

from life import step

block = {(0, 0), (1, 0), (0, 1), (1, 1)}
blinker = {(0, 1), (1, 1), (2, 1)}
glider = {(1, 0), (2, 1), (0, 2), (1, 2), (2, 2)}

print("block unchanged after 1 step:  ", step(block) == block)
print("blinker back after 2 steps:    ", step(step(blinker)) == blinker, "(but not after 1:", step(blinker) == blinker, ")")
g = glider
for _ in range(4):
    g = step(g)
moved = {(x + 1, y + 1) for x, y in glider}
print("glider after 4 steps = same shape moved one square diagonally:", g == moved)
